from fastapi.testclient import TestClient
from careflow.api.app import app
import uuid

client = TestClient(app)


def test_openapi_schema_generation():
    """Verify OpenAPI 3.1.0 schema generated by FastAPI Self-Directed Tool."""
    response = client.get("/openapi.json")
    assert response.status_code == 200
    schema = response.json()
    assert schema["info"]["title"] == "CareFlow Clinic Management API"
    assert "/api/appointments/book" in schema["paths"]
    assert "/api/billing/pay" in schema["paths"]
    assert "UserRegisterRequest" in schema["components"]["schemas"]


def test_health_check_endpoint():
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json()["status"] == "HEALTHY"


def test_api_full_registration_and_booking_flow():
    unique_id = uuid.uuid4().hex[:6]
    doc_email = f"dr.{unique_id}@ruet.ac.bd"
    pat_email = f"pat.{unique_id}@ruet.ac.bd"

    # 1. Register Doctor
    doc_resp = client.post(
        "/api/auth/register",
        json={
            "name": f"Dr. Test {unique_id}",
            "email": doc_email,
            "password": "Password123",
            "role": "DOCTOR",
            "phone": "01711223344",
        },
    )
    assert doc_resp.status_code == 201
    doc_data = doc_resp.json()["user"]

    # 2. Register Patient
    pat_resp = client.post(
        "/api/auth/register",
        json={
            "name": f"Patient Test {unique_id}",
            "email": pat_email,
            "password": "Password123",
            "role": "PATIENT",
            "phone": "01811223344",
        },
    )
    assert pat_resp.status_code == 201
    pat_data = pat_resp.json()["user"]

    # 3. Login
    login_resp = client.post(
        "/api/auth/login",
        json={"email": pat_email, "password": "Password123"},
    )
    assert login_resp.status_code == 200
    assert "access_token" in login_resp.json()

    # 4. Book Appointment
    slot_time = f"2026-12-01T{unique_id[:2]}:00:00"
    book_resp = client.post(
        "/api/appointments/book",
        json={
            "patient_id": pat_data["user_id"],
            "doctor_id": doc_data["user_id"],
            "scheduled_time": slot_time,
            "reason": "Routine Annual Health Examination",
            "fee": 1200.0,
        },
    )
    assert book_resp.status_code == 201
    appt_data = book_resp.json()["appointment"]
    appt_id = appt_data["appointment_id"]

    # 5. Prevent Duplicate Slot Collision
    dup_resp = client.post(
        "/api/appointments/book",
        json={
            "patient_id": pat_data["user_id"],
            "doctor_id": doc_data["user_id"],
            "scheduled_time": slot_time,
            "reason": "Conflicting Second Booking",
            "fee": 1200.0,
        },
    )
    assert dup_resp.status_code == 400
    assert "already booked" in dup_resp.json()["detail"]

    # 6. Confirm Appointment
    confirm_resp = client.put(f"/api/appointments/{appt_id}/confirm")
    assert confirm_resp.status_code == 200
    assert confirm_resp.json()["appointment"]["status"] == "CONFIRMED"

    # 7. Generate Invoice with Student Subsidy
    inv_resp = client.post(
        "/api/billing/generate",
        json={"appointment_id": appt_id, "scheme": "STUDENT"},
    )
    assert inv_resp.status_code == 201
    inv_data = inv_resp.json()["invoice"]
    assert inv_data["total_payable"] == 840.0  # 1200 - 30% discount = 840

    # 8. Settle Payment via bKash Adapter
    pay_resp = client.post(
        "/api/billing/pay",
        json={
            "invoice_id": inv_data["invoice_id"],
            "gateway": "BKASH",
            "phone": "01811223344",
        },
    )
    assert pay_resp.status_code == 200
    assert pay_resp.json()["gateway"] == "bKash-Payment-Gateway"
    assert pay_resp.json()["amount_paid"] == 840.0

    # 9. Record Consultation & Prescription
    rec_resp = client.post(
        "/api/records/prescribe",
        json={
            "appointment_id": appt_id,
            "diagnosis": "Mild Essential Hypertension",
            "notes": "Reduce dietary sodium intake.",
            "prescriptions": [
                {
                    "medicine_name": "Amlodipine",
                    "dosage": "5mg",
                    "frequency": "1-0-0 in morning",
                    "duration_days": 30,
                }
            ],
        },
    )
    assert rec_resp.status_code == 201
    rec_data = rec_resp.json()["record"]
    assert rec_data["diagnosis"] == "Mild Essential Hypertension"
    assert len(rec_data["prescriptions"]) == 1

